/* CASE 03｜地是我的，為什麼不能拆？唯一流程來源。 */
(function(){
  const fresh=()=>({site:false,wall:false,land:false,boundaryStarted:false,measure:false,docs:[],initialJudgment:null,restore:null,history:[],currentHtml:'',currentKey:'',reviewIndex:null});
  const data=()=>s.case3Runtime||(s.case3Runtime=fresh());
  const clear=()=>document.querySelectorAll('#modal').forEach(node=>node.remove());
  const modal=html=>{clear();app.insertAdjacentHTML('beforeend','<section class="panel c3-panel" id="modal">'+html+'</section>')};
  const addDoc=id=>{const d=data();if(!d.docs.includes(id))d.docs.push(id)};
  const filesButton=()=>data().docs.length?'<button class="c3-files" onclick="c3OpenFiles()">📁 案件資料</button>':'';
  const desk=()=>{app.innerHTML='<section class="c3-review"><div class="shade"></div><header class="top"><div><b>案件三｜地是我的，為什麼不能拆？</b><br><small>深夜案件審查室</small></div></header>'+filesButton()+'</section>'};
  const retry=(text,next)=>modal('<p>'+text+'</p><button class="primary" onclick="'+next+'()">再想想</button>');
  const backButton=()=>data().history.length>1?'<button class="c3-review-back" onclick="c3ReviewPrevious()">← 回看上一步</button>':'';
  const renderCurrent=()=>{const d=data();d.reviewIndex=null;modal(d.currentHtml+backButton())};
  const view=(key,title,review,html)=>{const d=data();d.currentKey=key;d.currentHtml=html;d.reviewIndex=null;const last=d.history[d.history.length-1];if(!last||last.key!==key)d.history.push({key,title,review,html,answer:null});else{last.review=review;last.html=html}renderCurrent()};
  const markReview=(key,review,answer)=>{const entry=[...data().history].reverse().find(item=>item.key===key);if(entry){entry.review=review;entry.answer=answer||entry.answer}};
  const initialText=()=>data().initialJudgment==='support'?'支持拆除越界部分':'暫不支持拆除越界部分';

  const reviewPage=entry=>{const holder=document.createElement('div'),answer=entry.answer||((entry.review||'').match(/你的答案：([A-D])/ )||[])[1]||((entry.review||'').includes('初步判斷：支持')?'A':(entry.review||'').includes('初步判斷：暫不支持')?'B':'');holder.innerHTML=entry.html||'';holder.querySelectorAll('button').forEach(button=>{button.removeAttribute('onclick');button.disabled=true;button.classList.add('c3-review-locked');if(answer&&button.classList.contains('choice')&&new RegExp('^'+answer+'[　｜. ]').test(button.textContent.trim()))button.classList.add('c3-review-selected')});return '<div class="c3-review-page">'+holder.innerHTML+'</div>'+(entry.review?'<div class="c3-review-answer">'+entry.review+'</div>':'')+'<p class="note c3-review-note">回看模式：原頁面內容與圖像均保留；已作答的選項不可修改。</p>'};
  window.c3ReviewPrevious=function(){const d=data(),index=Number.isInteger(d.reviewIndex)?d.reviewIndex-1:d.history.length-2;if(index<0)return;d.reviewIndex=index;const previous=d.history[index];modal(reviewPage(previous)+'<div class="c3-review-controls">'+(index>0?'<button class="c3-review-back" onclick="c3ReviewPrevious()">← 返回上一頁</button>':'')+'<button class="primary" onclick="c3ContinueCurrent()">繼續目前進度</button></div>')};
  window.c3ContinueCurrent=function(){data().reviewIndex=null;renderCurrent()};

  const field=()=>{const d=data();let step,note;
    if(!d.site){step='<button class="c3-hot c3-site" onclick="c3SiteMap()">● 查看現場位置圖</button>';note='先確認上、下兩地與擋土牆的位置。'}
    else if(!d.wall){step='<button class="c3-wall-hit" onclick="c3Wall()" aria-label="查看擋土牆"></button><button class="c3-hot c3-wall" onclick="c3Wall()">● 查看擋土牆</button>';note='看看這道牆在兩地高低差之間的作用。'}
    else if(!d.land){step='<button class="c3-hot c3-land" onclick="c3LandData()">● 查閱土地資料</button>';note='接著確認下方社區共有土地的權利關係。'}
    else if(!d.boundaryStarted){step='<button class="c3-hot c3-boundary" onclick="c3Boundary()">● 確認土地界線</button>';note='確認真正的土地界線。'}
    else {step='<span class="c3-field-status">正在核對土地界線資料</span>';note='真正的土地界線需要依測量結果確認。'}
    app.innerHTML='<section class="c3-field"><header class="top"><div><b>現場調查</b><br><small>'+note+'</small></div></header>'+filesButton()+step+'</section>';
  };

  const sitePlan=()=>'<div class="c3-site-plan"><img src="assets/case3_site_plan_oblique_v4.png" alt="上方住宅開發基地、中央整面垂直擋土牆與下方既有住宅社區"><span class="plan-high">較高處</span><b class="plan-neighbor">住宅開發基地<small>被告承造工程</small></b><b class="plan-wall">擋土牆</b><b class="plan-disputed">既有住宅社區<small>下方土地為社區共有</small></b><span class="plan-low">較低處</span></div>';
  const wallSection=()=>'<div class="c3-section c3-section-new"><div class="c3-high-ground"><b>上方開發基地／較高處</b><span class="c3-soil">較高處土體</span><span class="c3-soil-grain">土　土　土　土<br>土　土　土　土<br>土　土　土　土</span><span class="c3-pressure">土體側向壓力　→ → →</span></div><div class="c3-retain-wall"><span>擋土牆</span></div><div class="c3-low-platform"><em>下方社區／較低處</em></div></div>';
  // CASE 03 的所有測量頁共用這一份平面測量幾何；甲、乙是同一牆體越過地界的小部分。
  const measurementDiagram=(reveal=0,emphasis='')=>'<div class="c3-measure-plan c3-measure-new reveal-'+reveal+' '+emphasis+'"><b class="mp-neighbor">開發基地側<small>地勢較高</small></b><b class="mp-disputed">社區共有土地側<small>地勢較低</small></b><svg class="mp-svg" viewBox="0 0 320 150" role="img" aria-label="擋土牆實際占地範圍與真正土地界線的平面測量圖"><defs><pattern id="c3-area-hatch" width="6" height="6" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="6" height="6" fill="#efd59f"></rect><line x1="0" y1="0" x2="0" y2="6" stroke="#946538" stroke-width="2"></line></pattern></defs><path class="mp-wall-shape" d="M18 51 L61 50 L96 53 L139 52 L183 54 L222 51 L274 53 L300 57 L298 85 L272 87 L264 91 L261 98 L253 103 L246 99 L242 91 L188 90 L182 94 L178 101 L170 108 L159 106 L153 99 L150 91 L125 89 L101 91 L64 90 L18 88 Z"></path><path class="mp-wall-texture" d="M25 62 L292 66 M26 76 L295 79"></path><path class="mp-area-shape area-a" d="M150 91 L188 90 L182 94 L178 101 L170 108 L159 106 L153 99 Z"></path><path class="mp-area-shape area-b" d="M242 91 L264 91 L261 98 L253 103 L246 99 Z"></path><line class="mp-boundary-svg" x1="12" y1="91" x2="308" y2="91"></line><text class="mp-wall-label" x="154" y="72" text-anchor="middle">擋土牆實際占地範圍</text><text class="mp-boundary-label" x="220" y="38">真正土地界線</text><g class="mp-area-label area-a-label"><text x="168" y="101" text-anchor="middle">甲</text><text x="168" y="114" text-anchor="middle">1.83㎡</text></g><g class="mp-area-label area-b-label"><text x="252" y="99" text-anchor="middle">乙</text><text x="252" y="111" text-anchor="middle">1.69㎡</text></g></svg><b class="mp-range-label">本案爭議範圍＝甲＋乙</b></div>';

  const docViews={
    site:()=>'<h2>🗺️ 現場位置圖</h2>'+sitePlan()+'<p>這不是精密地籍測量圖，只用來確認上方開發基地、下方社區與擋土牆的相對位置。</p>',
    wall:()=>'<h2>🧱 擋土牆資料</h2>'+wallSection()+'<p>擋土牆不是普通的圍牆；它攔住、支撐較高處後方的土體，維持兩地高低差。</p>',
    land:()=>'<h2>📄 土地資料</h2><p><b>下方土地：</b><br>既有住宅社區住戶共有</p><p><b>本案原告：</b><br>社區共有人之一</p><p>下方這筆土地不是原告一個人的，而是社區住戶共同所有。原告為全體共有人利益，請求排除土地受到的占用。</p>',
    measure:()=>'<h2>📐 測量結果圖</h2>'+measurementDiagram(2,'doc')+'<p>擋土牆有兩小部分跨過真正土地界線，進入下方社區共有土地。</p><p><b>本案爭議範圍：甲1.83㎡＋乙1.69㎡，合計3.52㎡。</b></p>',
    defendant:()=>'<h2>📄 被告答辯</h2><p>「擋土牆具有維持邊坡穩定的功能。」</p><p>「越界部分面積很小，只有3.52㎡。」</p><p>「如果要求拆除，可能影響擋土牆及邊坡安全。」</p><p class="case-tag">被告主張：原告的拆除請求構成權利濫用。</p>',
    evidence:()=>'<h2>🔎 證據檢查</h2><div class="c3-evidence-grid"><p class="confirmed">✓ 已確認<br><b>整座擋土牆具有重要功能</b></p><p class="unproven">？ 尚未證明<br><b>拆除甲、乙共3.52㎡的越界部分，一定會造成重大安全影響</b></p></div>',
    law:()=>'<h2>⚖️ 《民法》第148條</h2><p>「權利之行使，不得違反公共利益，或<b class="c3-mark">以損害他人為主要目的</b>。<br><br>行使權利，履行義務，應依誠實及信用方法。」</p>'
  };
  const docNames={site:'🗺️ 現場位置圖',wall:'🧱 擋土牆資料',land:'📄 土地資料',measure:'📐 測量結果圖',defendant:'📄 被告答辯',evidence:'🔎 證據檢查',law:'⚖️ 民法第148條'};
  window.c3OpenFiles=function(){const d=data(),active=document.querySelector('#modal');if(d.restore===null)d.restore=active?active.innerHTML:'';modal('<h2>📁 案件資料夾</h2><p class="note">可重新查看已取得的資料。</p>'+d.docs.map(id=>'<button class="item" onclick="c3OpenDoc(\''+id+'\')">'+docNames[id]+'</button>').join('')+'<button class="primary" onclick="c3CloseFiles()">返回原畫面</button>')};
  window.c3OpenDoc=id=>modal(docViews[id]()+ '<button class="primary" onclick="c3OpenFiles()">返回案件資料夾</button>');
  window.c3CloseFiles=function(){const d=data();if(d.restore){modal(d.restore);d.restore=null}else clear()};

  window.case3Start=function(){s.case3=[];s.case3Runtime=fresh();desk();modal('<h2>案件三｜地是我的，為什麼不能拆？</h2><p class="case-tag">真實法律爭議改編</p><p>本案改編自臺灣基隆地方法院110年度基簡字第488號民事判決，為教學需要簡化部分事實。</p><p>一處住宅開發基地與既有社區相鄰。由於兩地具有明顯高低差，開發工程在兩地之間設置了一道擋土牆。</p><p>後來，土地測量發現——這道擋土牆有一小部分，可能跨進下方社區的共有土地。</p><p>社區的一名共有人因此提出請求：「如果擋土牆真的占到我們的土地，就應該把越界的部分拆除、返還土地。」</p><p><b>本案請求的核心是：拆除越界部分。</b></p><button class="primary" onclick="c3FirstField()">前往現場</button>')};
  window.c3FirstField=function(){clear();field()};
  window.c3SiteMap=function(){view('site','現場位置圖','<p>位置圖只確認上下兩側與擋土牆的相對位置；尚未顯示真正土地界線。</p>','<h2>現場位置圖</h2>'+sitePlan()+'<p>這張圖只用來確認現場空間關係，還沒有顯示真正的土地界線。</p><h3>從現場位置圖，現在可以先確認什麼？</h3><button class="choice" onclick="c3SiteAnswer(\'A\')">A　擋土牆就是兩筆土地的真正地界</button><button class="choice" onclick="c3SiteAnswer(\'B\')">B　上方開發基地與下方既有社區有明顯高低差，兩者之間設有擋土牆</button><button class="choice" onclick="c3SiteAnswer(\'C\')">C　擋土牆已確定越界3.52㎡</button>')};
  window.c3SiteAnswer=function(answer){if(answer==='A'){retry('位置圖只能確認相對位置，真正的土地界線還要查看測量結果。','c3SiteMap');return}if(answer==='C'){retry('目前還沒有查看測量結果，還不能知道實際越界範圍。','c3SiteMap');return}markReview('site','<p><b>你的答案：B</b></p><p>現在只能確認兩地的相對位置，以及擋土牆的位置；真正地界仍待測量確認。</p>');modal('<h2>現場位置圖</h2><p>沒錯。</p><p>現在只能確認兩地的相對位置，以及擋土牆的位置。</p><p>真正的土地界線在哪裡，還要進一步確認。</p><button class="primary" onclick="c3SiteSaved()">記錄位置</button>')};
  window.c3SiteSaved=function(){data().site=true;addDoc('site');clear();field()};
  window.c3Wall=function(){view('wall','擋土牆是做什麼的？','<p>擋土牆的一般功能，是支撐、攔住較高一側後方的土體；這不表示本案越界部分一定不能拆除。</p>','<h2>擋土牆是做什麼的？</h2>'+wallSection()+'<p>擋土牆不是普通的圍牆。</p><p>兩地有明顯高低差時，擋土牆可以攔住、支撐較高處後方的土體，維持邊坡及高低差。</p><p><b>圍牆</b>主要用來區隔空間。<br><b>擋土牆</b>主要用來攔住、支撐後方土體。</p><button class="primary" onclick="c3WallFunctionQuestion()">確認理解</button>')};
  window.c3WallFunctionQuestion=function(){view('wall-question','擋土牆理解','<p>這道牆主要攔住、支撐較高處後方的土體。</p>','<h2>擋土牆理解</h2><p>這道擋土牆主要是在「擋」什麼？</p><button class="choice" onclick="c3WallFunctionAnswer(\'A\')">A　兩邊的居民</button><button class="choice" onclick="c3WallFunctionAnswer(\'B\')">B　土地界線</button><button class="choice" onclick="c3WallFunctionAnswer(\'C\')">C　較高處後方的土體</button><button class="choice" onclick="c3WallFunctionAnswer(\'D\')">D　下方住宅</button>')};
  window.c3WallFunctionAnswer=function(answer){if(answer!=='C'){retry('再看看剖面圖：箭頭顯示的是較高處後方土體向外產生的作用。','c3WallFunctionQuestion');return}data().wall=true;addDoc('wall');markReview('wall-question','<p><b>你的答案：C｜較高處後方的土體</b></p><p>擋土牆不是普通圍牆，而是攔住、支撐高處後方的土體。</p>');modal('<h2>擋土牆理解</h2><p>沒錯。</p><p>它不是單純區隔兩戶的圍牆，而是用來攔住、支撐較高處後方的土體。</p><p>取得：🧱 擋土牆資料</p><button class="primary" onclick="c3WallSaved()">記錄資料</button>')};
  window.c3WallSaved=function(){clear();field()};
  window.c3LandData=function(){view('land','土地資料','<p>下方土地由既有住宅社區住戶共有；原告是共有人之一，為全體共有人利益請求排除占用。</p>','<h2>土地資料</h2><p><b>下方土地：</b><br>既有住宅社區住戶共有</p><p><b>本案原告：</b><br>社區共有人之一</p><p>也就是說，下方這筆土地不是原告一個人的，而是社區住戶共同所有。原告是其中一名共有人，本案為全體共有人利益，請求排除土地受到的占用。</p><button class="primary" onclick="c3LandSaved()">記錄資料</button>')};
  window.c3LandSaved=function(){data().land=true;addDoc('land');clear();field()};
  window.c3Boundary=function(){data().boundaryStarted=true;field();view('boundary','確認土地界線','<p>只看現場構造物的位置，不能確定真正地界；需要查看實際測量結果。</p>','<h2>確認土地界線</h2><p>現在知道：下方土地屬於社區住戶共有。</p><p>但是——擋土牆真的蓋進這筆土地了嗎？</p><p>只看現場外觀，能不能確定真正的土地界線？</p><button class="choice" onclick="c3BoundaryAnswer(\'A\')">A　可以，擋土牆的位置就是地界</button><button class="choice" onclick="c3BoundaryAnswer(\'B\')">B　不能只靠現場外觀確定</button>')};
  window.c3BoundaryAnswer=function(answer){if(answer!=='B'){retry('牆面、圍牆或其他構造物的位置，不一定就是真正的土地界線。','c3Boundary');return}markReview('boundary','<p><b>你的答案：B</b></p><p>擋土牆是實際構造物，但它的位置不一定就是土地界線。</p>');modal('<h2>確認土地界線</h2><p>沒錯。要確認是否越界，需要查看實際測量結果。</p><button class="primary" onclick="c3MeasureQuestion()">查看測量結果</button>')};
  window.c3MeasureQuestion=function(){view('measure-alignment','測量結果圖','<p>先對照擋土牆實際位置與真正土地界線；此時尚未標示甲、乙範圍。</p>','<h2>測量結果圖</h2>'+measurementDiagram(0)+'<p>先看擋土牆的平面位置與真正土地界線。</p><h3>擋土牆的位置和真正土地界線完全重合嗎？</h3><button class="choice" onclick="c3MeasureAlignmentAnswer(\'A\')">A　完全重合</button><button class="choice" onclick="c3MeasureAlignmentAnswer(\'B\')">B　沒有完全重合</button>')};
  window.c3MeasureAlignmentAnswer=function(answer){if(answer!=='B'){retry('再看牆體平面範圍：它有局部位置越過了橫向虛線。','c3MeasureQuestion');return}markReview('measure-alignment','<p><b>你的答案：B｜沒有完全重合</b></p><p>牆體有局部跨過真正土地界線。</p>');c3MeasureRevealA()};
  window.c3MeasureRevealA=function(){view('measure-a','第一處跨界範圍','<p>甲區域是擋土牆本體向下跨過真正土地界線、進入社區共有土地的一小部分。</p>','<h2>第一處跨界範圍</h2>'+measurementDiagram(1,'focus-a')+'<p><b>甲區域：1.83㎡</b></p><p>這一小段牆體跨過真正土地界線，進入下方社區共有土地。</p><button class="primary" onclick="c3MeasureRevealB()">繼續查看</button>')};
  window.c3MeasureRevealB=function(){view('measure-b','第二處跨界範圍','<p>乙區域同樣是牆體本身向下跨過地界的一小部分。</p>','<h2>第二處跨界範圍</h2>'+measurementDiagram(2,'focus-both')+'<p><b>乙區域：1.69㎡</b></p><p>現在可看見兩個跨界的牆體部分。甲1.83㎡＋乙1.69㎡＝？</p><button class="choice" onclick="c3MeasureAnswer(\'2.52\')">A　2.52㎡</button><button class="choice" onclick="c3MeasureAnswer(\'3.12\')">B　3.12㎡</button><button class="choice" onclick="c3MeasureAnswer(\'3.52\')">C　3.52㎡</button><button class="choice" onclick="c3MeasureAnswer(\'4.52\')">D　4.52㎡</button>')};
  window.c3MeasureAnswer=function(answer){if(answer!=='3.52'){retry('再確認甲、乙兩個區域的面積。','c3MeasureRevealB');return}data().measure=true;addDoc('measure');markReview('measure-b','<p><b>你的答案：C｜3.52㎡</b></p><p>甲1.83㎡與乙1.69㎡合計3.52㎡。</p>');view('measure-total','本案爭議範圍合計','<p><b>你的答案：C｜3.52㎡</b></p><p>原告要求拆除的是越界的甲、乙部分，不是整座擋土牆。</p>','<h2>本案爭議範圍合計：3.52㎡</h2>'+measurementDiagram(2,'focus-both final')+'<p>也就是說——要求拆除的，不是整座擋土牆，而是越過地界的甲、乙兩個部分。</p><button class="primary" onclick="c3AfterMeasure()">我看懂爭議位置了</button>')};
  window.c3AfterMeasure=function(){c3InitialNew()};
  window.c3InitialNew=function(){desk();view('initial','初步判斷','<p>原告要求拆除越界甲、乙部分並返還被占用土地。這一題是初步判斷，尚非正誤題。</p>','<h2>目前可以確認</h2><p>✓ 上方是住宅開發基地<br>✓ 下方是既有社區共有土地<br>✓ 兩地有明顯高低差<br>✓ 中間設有具有擋土功能的擋土牆<br>✓ 擋土牆有兩小部分跨進下方土地<br>✓ 越界部分合計3.52㎡</p><p>原告要求：拆除越界的甲、乙部分，並返還被占用的土地。</p><h3>依目前掌握的資料，你會怎麼處理這項請求？</h3><button class="choice" onclick="c3InitialChoice(\'support\')"><b>A｜支持拆除越界部分</b><br><small>擋土牆確實占用了共有土地。</small></button><button class="choice" onclick="c3InitialChoice(\'hesitate\')"><b>B｜暫不支持拆除越界部分</b><br><small>雖然確實越界，但也應考量拆除可能造成的影響。</small></button>')};
  window.c3InitialChoice=function(choice){data().initialJudgment=choice;markReview('initial','<p><b>你的初步判斷：'+initialText()+'</b></p><p>這是證據尚未完整前的初步想法，不是正誤題。</p>');modal('<h2>初步判斷已記錄</h2><p>你的初步判斷：<b>'+initialText()+'。</b></p><button class="primary" onclick="c3Defendant()">查看被告答辯</button>')};
  window.c3Defendant=function(){addDoc('defendant');desk();view('defendant','被告答辯','<p>被告主張：拆除越界部分可能影響擋土牆與邊坡安全，並據此主張原告的請求是權利濫用。</p>','<h2>被告答辯</h2><p>「擋土牆具有維持邊坡穩定的功能。」</p><p>「越界部分面積很小，只有3.52㎡。」</p><p>「如果要求拆除，可能影響擋土牆及邊坡安全。」</p><p>「在這種情況下仍要求拆除，是否已經超過權利行使的界線？」</p><hr><p class="case-tag">被告主張：原告的拆除請求構成權利濫用。</p><button class="primary" onclick="c3EvidenceNeedQuestion()">檢查被告主張</button>')};
  window.c3EvidenceNeedQuestion=function(){view('evidence-question','關鍵證據問題','<p>被告提出安全影響的主張，但仍須確認拆除甲、乙越界部分是否真的會造成所稱重大影響。</p>','<h2>關鍵證據問題</h2><p>被告說：拆除這3.52㎡的越界部分，可能影響整座擋土牆與邊坡安全。</p><p>要判斷這個主張，還缺什麼？</p><button class="choice" onclick="c3EvidenceNeedAnswer(\'A\')">A　原告有沒有住在社區</button><button class="choice" onclick="c3EvidenceNeedAnswer(\'B\')">B　拆除越界部分，是否真的會造成被告所說的重大影響</button><button class="choice" onclick="c3EvidenceNeedAnswer(\'C\')">C　擋土牆看起來漂不漂亮</button>')};
  window.c3EvidenceNeedAnswer=function(answer){if(answer!=='B'){retry('被告提出的是安全影響的主張，因此要確認的正是拆除越界部分會不會真的造成重大影響。','c3EvidenceNeedQuestion');return}markReview('evidence-question','<p><b>你的答案：B</b></p><p>被告的安全影響主張，仍需要具體證據支持。</p>');c3EvidenceCheck()};
  window.c3EvidenceCheck=function(){addDoc('evidence');desk();view('evidence','案件資料檢查','<p>已確認整座牆具有重要功能；但尚未證明拆除甲、乙共3.52㎡的越界部分一定造成重大安全影響。</p>','<h2>案件資料檢查</h2><div class="c3-evidence-grid"><p class="confirmed">✓ 已確認<br><b>整座擋土牆具有水土保持及邊坡安全功能</b></p><p class="unproven">？ 尚未證明<br><b>拆除甲、乙共3.52㎡的越界部分，一定會造成被告所稱的重大安全影響</b></p></div><p>主張 ≠ 已經證明的事實</p><button class="primary c3-lawbook" onclick="c3Article()">查看民法第148條</button>')};
  window.c3Article=function(){addDoc('law');view('law','《民法》第148條','<p>本案聚焦禁止權利濫用：權利存在，仍需依具體事實與證據判斷其行使是否逾越界線。</p>','<h2>《民法》第148條</h2><p>「權利之行使，不得違反公共利益，<br>或<b class="c3-mark">以損害他人為主要目的</b>。<br><br>行使權利，履行義務，<br>應依誠實及信用方法。」</p><p>本案主要聚焦：禁止權利濫用。</p><button class="primary" onclick="c3AbuseReview()">整理判斷材料</button>')};
  window.c3AbuseReview=function(){view('abuse','權利濫用判斷','<p><b>你一開始的判斷：'+initialText()+'</b></p><p>僅因被告可能受到不利益，還不能直接認定原告是以損害他人為主要目的。</p>','<h2>權利濫用判斷</h2><p><b>你一開始的判斷：</b>'+initialText()+'</p><p><b>原告的權利</b><br>✓ 下方共有土地確實受到占用<br>✓ 原告為全體共有人利益請求排除占用</p><p><b>被告的利益</b><br>✓ 擋土牆具有實際功能<br>✓ 拆除可能對被告造成影響</p><p><b>關鍵</b><br>目前沒有證明，拆除甲、乙越界部分，必然造成被告主張的重大安全後果。</p><p>僅僅因為被告可能受到較大的不利益，就可以認定原告是「以損害他人為主要目的」嗎？</p><button class="choice" onclick="c3AbuseAnswer(\'A\')">A　可以</button><button class="choice" onclick="c3AbuseAnswer(\'B\')">B　不能只靠這一點認定</button>')};
  window.c3AbuseAnswer=function(answer){if(answer!=='B'){retry('被告可能受到不利益，是判斷材料；但還不能只靠這一點認定原告主要是為了損害對方。','c3AbuseReview');return}markReview('abuse','<p><b>你的答案：B｜不能只靠這一點認定</b></p><p>不利益與利益差距都需要放回具體事實與證據中判斷。</p>');c3Court()};
  window.c3Court=function(){desk();view('court','法院判決','<p>法院只命拆除越界的甲、乙部分，共3.52㎡，不是整座擋土牆。</p>','<h2>法院判決</h2><p>法院沒有接受被告的「權利濫用」抗辯。</p><p>原告請求排除土地遭占用，是在維護共有土地的所有權。</p><p>雖然擋土牆具有重要功能，但被告沒有證明：拆除甲、乙兩個越界部分，就會造成其所主張的重大安全危險。</p><p>因此，不能只因被告可能受到較大的不利益，就認定原告的請求屬於權利濫用。</p>'+measurementDiagram(2,'focus-both judgment')+'<div class="c3-order"><b>法院命拆除範圍</b><br>甲 1.83㎡ ＋ 乙 1.69㎡ ＝ 3.52㎡<br><small>法院命拆除的是越界的甲、乙部分，不是整座擋土牆。</small></div><button class="primary" onclick="c3ExitQuestion1()">進行離場整理</button>')};
  window.c3ExitQuestion1=function(){view('exit-1','離場題一：回看本案','<p>本案中，被告所稱重大影響仍須依具體事實與證據判斷。</p>','<h2>回看本案</h2><p>本案中，原告要求拆除越界的甲、乙部分，可能使被告受到較大的不利益。法院為什麼仍沒有因此認定原告構成權利濫用？</p><button class="choice" onclick="c3Exit1Answer(\'A\')">A　只要土地遭到占用，所有權人行使權利就不可能構成權利濫用</button><button class="choice" onclick="c3Exit1Answer(\'B\')">B　只要占用面積很小，法院原則上就應命占用人拆除並返還土地</button><button class="choice" onclick="c3Exit1Answer(\'C\')">C　被告雖主張拆除影響重大，但相關損害仍須依具體事實加以判斷</button><button class="choice" onclick="c3Exit1Answer(\'D\')">D　擋土牆雖具有重要功能，但土地所有權原則上一定優先受到保障</button>')};
  window.c3Exit1Answer=function(answer){if(answer!=='C'){retry('再想想：被告所說的重大影響，是否已有具體事實與證據可以確認？','c3ExitQuestion1');return}markReview('exit-1','<p><b>你的答案：C</b></p><p>被告提出的重大影響，仍須依具體事實與證據判斷。</p>');modal('<h2>回看本案</h2><p>沒錯。法院不能只因可能造成不利益，就跳過對具體事實與證據的判斷。</p><button class="primary" onclick="c3ExitQuestion2()">下一題</button>')};
  window.c3ExitQuestion2=function(){view('exit-2','離場題二：可能構成權利濫用','<p>權利存在不表示任何使用方式都不會涉及權利濫用；仍要看目的與實際利益、損害。</p>','<h2>可能構成權利濫用的情況</h2><p>甲與鄰居長期不合。某天甲在自己的土地上設置障礙物。調查發現：這項設施對甲幾乎沒有實際用途，卻會使鄰居受到重大不利益。甲還曾表示：「我就是要讓他不能使用。」</p><p>與剛才的擋土牆案件相比，下列判斷何者較適當？</p><button class="choice" onclick="c3Exit2Answer(\'A\')">A　鄰居既然受到重大不利益，就已足以認定甲構成權利濫用</button><button class="choice" onclick="c3Exit2Answer(\'B\')">B　甲所得利益極少且以損害他人為主要目的，較可能涉及權利濫用</button><button class="choice" onclick="c3Exit2Answer(\'C\')">C　土地既然屬於甲所有，如何使用原則上都不會構成權利濫用</button><button class="choice" onclick="c3Exit2Answer(\'D\')">D　仍須先比較雙方土地面積大小，才能判斷是否構成權利濫用</button>')};
  window.c3Exit2Answer=function(answer){if(answer!=='B'){retry('再想想：除了鄰居受到不利益，甲自己有什麼實際利益？他的目的又是什麼？','c3ExitQuestion2');return}markReview('exit-2','<p><b>你的答案：B</b></p><p>所得利益極少、又以損害他人為主要目的時，較可能涉及權利濫用。</p>');modal('<h2>可能構成權利濫用的情況</h2><p>沒錯。這個情境比本案更可能涉及權利濫用，因為權利行使的目的與實際利益都值得檢視。</p><button class="primary" onclick="c3ExitQuestion3()">下一題</button>')};
  window.c3ExitQuestion3=function(){view('exit-3','離場題三：整理判斷因素','<p>判斷權利是否濫用，須觀察行使目的，並衡量所得利益與他人、國家社會所受損害。</p>','<h2>整理判斷因素</h2><p>綜合前面兩種情況，判斷權利是否遭到濫用時，下列何者最完整？</p><button class="choice" onclick="c3Exit3Answer(\'A\')">A　主要確認權利是否依法存在，只要權利存在即可自由行使</button><button class="choice" onclick="c3Exit3Answer(\'B\')">B　主要比較雙方受到的損害大小，損害較大的一方應受到保障</button><button class="choice" onclick="c3Exit3Answer(\'C\')">C　確認他人是否受到不利益，只要造成不利益就應限制權利</button><button class="choice" onclick="c3Exit3Answer(\'D\')">D　觀察權利行使目的，並衡量所得利益與他人、國家社會所受損害</button>')};
  window.c3Exit3Answer=function(answer){if(answer!=='D'){retry('再想想：不能只看權利是否存在、單一損害或單一利益，還要看行使目的與具體衡量。','c3ExitQuestion3');return}markReview('exit-3','<p><b>你的答案：D</b></p><p>判斷時須觀察權利行使目的，並衡量所得利益與他人、國家社會所受損害。</p>');modal('<h2>整理判斷因素</h2><p>沒錯。法律不是只看「有沒有權利」或「有沒有人受損」，還要回到行使目的與具體情況綜合判斷。</p><button class="primary" onclick="c3Concept()">整理原則</button>')};
  window.c3Concept=function(){desk();modal('<h2>🚫 禁止權利濫用原則</h2><p>有權利，不代表可以毫無界線地行使。</p><p>判斷權利的行使是否超過法律容許的界線，除了觀察<b>權利行使的目的</b>，實務上也會依具體情況衡量：</p><p class="c3-balance"><b>權利人所得利益</b><br>↕<br><b>他人及國家社會所受損害</b></p><p>「造成他人不利益」≠「當然構成權利濫用」<br>「雙方利益不相等」≠「當然構成權利濫用」</p><p><b>是否構成權利濫用，仍須依個案具體情況綜合判斷。</b></p><button class="primary" onclick="c3Complete()">完成案件三</button>')};
  window.c3Complete=function(){desk();modal('<h2>案件三・審查完成</h2><p>取得：<br><b>🚫 禁止權利濫用原則</b></p><p>判斷的重點不是「有沒有人受到不利益」，而是權利的行使是否已經超過法律容許的界線。</p><button class="primary" onclick="finish(\'c3\')">返回案件桌面</button>')};
  window.c3Summary=function(){window.openCompletedCaseSummary('c3')};
})();
